#!/usr/bin/env bash
# Seeds a tiny static app (Home, Hub, Reports) whose hand-off asks for three planted design problems: three doors to "New invoice",
# Hub a copy of Home, and an empty Reports page. Screenshots are committed, so no browser is needed. Fixed dates keep the shas stable.
set -euo pipefail
WS="${1:-$PWD}"
cd "$WS"
export GIT_AUTHOR_DATE="2026-11-21T10:00:00Z" GIT_COMMITTER_DATE="2026-11-21T10:00:00Z"
export GIT_AUTHOR_NAME=eval GIT_AUTHOR_EMAIL=eval@example.com GIT_COMMITTER_NAME=eval GIT_COMMITTER_EMAIL=eval@example.com
git init -q -b main .
git config user.email eval@example.com
git config user.name eval
mkdir -p design/handoff/M9 screenshots reviews
cat > CLAUDE.md <<'SEEDEOF'
# Tally

Invoicing app for small shops. English only. Targets: desktop 1440x900 and phone 390x844, light theme only.

- Owner: Jase. He gives every merge, deploy, send and publish go.
- Design hand-offs: `design/handoff/<milestone>/`. Design critiques: `reviews/CRITIQUE-<milestone>.md`.
- The app is static: `index.html` (Home), `hub.html` (Hub), `reports.html` (Reports), `styles.css`. Screenshots of the reviewed head: `screenshots/<page>-<desktop|phone>.png`.
- Findings go to the dev team's fixer.
SEEDEOF
cat > design/handoff/M9/README.md <<'SEEDEOF'
# M9 hand-off: Home, Hub and Reports

Acceptance notes:

- A1. "New invoice" is reachable everywhere: a button in the header, a link in the sidebar and a floating + button on every page.
- A2. Hub shows the same invoice table as Home, so people who look in either place find their invoices.
- A3. Reports exists in the sidebar now; its content comes in a later milestone, so the page shows its heading only.
SEEDEOF
cat > index.html <<'SEEDEOF'
<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Tally · Home</title><link rel="stylesheet" href="styles.css"></head>
<body>
<header><h1>Tally</h1><button class="btn" type="button">New invoice</button></header>
<div class="layout">
<nav aria-label="Main"><a href="index.html" class="on">Home</a><a href="hub.html">Hub</a><a href="reports.html">Reports</a><a href="#new">+ New invoice</a></nav>
<main>
<h2>Home</h2>
<table><thead><tr><th>Client</th><th>Amount</th><th>Due</th></tr></thead><tbody><tr><td>Rosa's Bakery</td><td>$240.00</td><td>Oct 3</td></tr><tr><td>Green Leaf Florist</td><td>$85.50</td><td>Oct 12</td></tr><tr><td>Harbor Books</td><td>$410.00</td><td>Oct 20</td></tr></tbody></table>
</main>
</div>
<button class="fab" type="button" aria-label="New invoice">+</button>
</body></html>
SEEDEOF
cat > hub.html <<'SEEDEOF'
<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Tally · Hub</title><link rel="stylesheet" href="styles.css"></head>
<body>
<header><h1>Tally</h1><button class="btn" type="button">New invoice</button></header>
<div class="layout">
<nav aria-label="Main"><a href="index.html">Home</a><a href="hub.html" class="on">Hub</a><a href="reports.html">Reports</a><a href="#new">+ New invoice</a></nav>
<main>
<h2>Hub</h2>
<table><thead><tr><th>Client</th><th>Amount</th><th>Due</th></tr></thead><tbody><tr><td>Rosa's Bakery</td><td>$240.00</td><td>Oct 3</td></tr><tr><td>Green Leaf Florist</td><td>$85.50</td><td>Oct 12</td></tr><tr><td>Harbor Books</td><td>$410.00</td><td>Oct 20</td></tr></tbody></table>
</main>
</div>
<button class="fab" type="button" aria-label="New invoice">+</button>
</body></html>
SEEDEOF
cat > reports.html <<'SEEDEOF'
<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Tally · Reports</title><link rel="stylesheet" href="styles.css"></head>
<body>
<header><h1>Tally</h1><button class="btn" type="button">New invoice</button></header>
<div class="layout">
<nav aria-label="Main"><a href="index.html">Home</a><a href="hub.html">Hub</a><a href="reports.html" class="on">Reports</a><a href="#new">+ New invoice</a></nav>
<main>
<h2>Reports</h2>
</main>
</div>
<button class="fab" type="button" aria-label="New invoice">+</button>
</body></html>
SEEDEOF
cat > styles.css <<'SEEDEOF'
body { margin: 0; font: 15px/1.45 system-ui, sans-serif; color: #1b1f24; background: #fff; }
header { display: flex; justify-content: space-between; align-items: center; padding: 12px 24px; border-bottom: 1px solid #e4e4e7; }
header h1 { font-size: 18px; margin: 0; }
.layout { display: grid; grid-template-columns: 200px 1fr; min-height: calc(100vh - 57px); }
nav { border-right: 1px solid #e4e4e7; padding: 16px; display: grid; gap: 8px; align-content: start; }
nav a { color: #1b1f24; text-decoration: none; padding: 6px 8px; border-radius: 8px; }
nav a.on { background: #f4f5f7; font-weight: 600; }
main { padding: 24px; }
main h2 { margin: 0 0 16px; font-size: 22px; }
.btn { background: #2457c5; color: #fff; border: 0; border-radius: 8px; padding: 10px 16px; font: inherit; font-weight: 600; }
table { width: 100%; border-collapse: collapse; }
td, th { text-align: left; padding: 10px 8px; border-bottom: 1px solid #e4e4e7; }
.fab { position: fixed; right: 24px; bottom: 24px; width: 56px; height: 56px; border-radius: 50%; background: #2457c5; color: #fff; border: 0; font-size: 28px; }
@media (max-width: 640px) { .layout { grid-template-columns: 1fr; } nav { border-right: 0; border-bottom: 1px solid #e4e4e7; grid-auto-flow: column; } }
SEEDEOF
